const body = $json.body || $json;

// ✅ FIX encoding UTF-8 bị lỗi (quan trọng nhất)
function fixEncoding(str) {
  try {
    return Buffer.from(str, "latin1").toString("utf8");
  } catch (e) {
    return str;
  }
}

// ✅ NORMALIZE TEXT (production-ready)
function normalize(str) {
  str = fixEncoding(str);

  return (str || "")
    .normalize("NFD") // tách dấu
    .replace(/[\u0300-\u036f]/g, "") // remove dấu
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .replace(/[^a-zA-Z0-9\s]/g, " ") // remove ký tự đặc biệt
    .toLowerCase()
    .replace(/\s+/g, " ") // clean multiple spaces
    .trim();
}

// ✅ Lấy raw input
const rawComment = String(
  body.comment || body.text || body.message || ""
).trim();

const sourceUser = String(
  body.user_id || body.source_user || body.username || "anonymous"
).trim();

const requestId = body.request_id || Date.now().toString();

// ✅ EMPTY CHECK
if (!rawComment) {
  return [
    {
      json: {
        skip: true,
        reason: "empty_comment",
        comment_raw: "",
        comment: "",
        source_user: sourceUser,
        request_id: requestId,
      },
    },
  ];
}

// ✅ SPAM CHECK (dùng RAW để không miss link)
const spamPatterns = [
  /https?:\/\//i,
  /t\.me\//i,
  /telegram/i,
  /casino/i,
  /bet/i,
  /crypto/i,
];

const isSpam = spamPatterns.some((r) => r.test(rawComment));

// ✅ NORMALIZE SAU KHI CHECK SPAM
const normalizedComment = normalize(rawComment);

// ✅ DEBUG (nên bật khi test)
console.log({
  raw: rawComment,
  fixed: fixEncoding(rawComment),
  normalized: normalizedComment,
});

// ✅ FINAL OUTPUT (LUÔN ARRAY)
return [
  {
    json: {
      skip: isSpam,
      reason: isSpam ? "spam_pattern" : "",

      // ✅ giữ cả raw + normalized
      comment_raw: rawComment,
      comment: normalizedComment,

      source_user: sourceUser,
      request_id: requestId,
    },
  },
];

