const normalize = $('Normalize + Basic Filter').first().json;

function fallback(reason, rawValue = null) {
  return [{
    json: {
      reply: 'Mình chưa hiểu rõ câu hỏi, bạn nói lại giúp mình nha!',
      emotion: 'neutral',
      action: 'fallback',
      source_user: normalize.source_user,
      comment: normalize.comment,
      request_id: normalize.request_id,
      llm_parse_ok: false,
      llm_parse_reason: reason,
      llm_raw_debug: rawValue
    }
  }];
}

const choice = $json.choices?.[0];

if (!choice) {
  return fallback('missing_choices', $json);
}

const msg = choice.message;

if (!msg) {
  return fallback('missing_message', $json);
}

let raw = '';

// Case 1: GPT/chat completion classic content string
if (typeof msg.content === 'string') {
  raw = msg.content;
}

// Case 2: Some newer model wrappers return content array
else if (Array.isArray(msg.content)) {
  raw = msg.content
    .map(x => {
      if (typeof x === 'string') return x;
      if (typeof x?.text === 'string') return x.text;
      if (typeof x?.content === 'string') return x.content;
      return '';
    })
    .join('');
}

// Case 3: Some endpoint wrappers expose output_text
else if (typeof $json.output_text === 'string') {
  raw = $json.output_text;
}

else {
  return fallback('unknown_content_format', msg);
}

raw = String(raw || '').trim();

if (!raw) {
  return fallback('empty_llm_content', {
    finish_reason: choice.finish_reason,
    usage: $json.usage,
    message: msg
  });
}

// Remove markdown fences if model ignores instruction
raw = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let data;

try {
  data = JSON.parse(raw);
} catch (e1) {
  try {
    data = JSON.parse(JSON.parse(raw));
  } catch (e2) {
    return fallback('json_parse_failed: ' + e2.message, raw);
  }
}

const allowedEmotions = new Set([
  'neutral',
  'happy',
  'excited',
  'sad',
  'angry'
]);

const allowedActions = new Set([
  'answer',
  'sell',
  'ignore',
  'fallback'
]);

let reply = String(data.reply || '').trim();
let emotion = String(data.emotion || 'neutral').trim().toLowerCase();
let action = String(data.action || 'fallback').trim().toLowerCase();

if (!allowedEmotions.has(emotion)) {
  emotion = 'neutral';
}

if (!allowedActions.has(action)) {
  action = 'fallback';
}

if (!reply && action !== 'ignore') {
  reply = 'Mình chưa hiểu rõ câu hỏi, bạn nói lại giúp mình nha!';
  action = 'fallback';
}

if (reply.length > 500) {
  reply = reply.slice(0, 497) + '...';
}

return [{
  json: {
    reply,
    emotion,
    action,
    source_user: normalize.source_user,
    comment: normalize.comment,
    request_id: normalize.request_id,
    llm_parse_ok: true
  }
}];

const input = $input.first().json;

const userId = input.source_user || input.user || "anonymous";

// ✅ đúng API static data của n8n Code node
const store = $getWorkflowStaticData("global");

// tạo key riêng cho memory
const memoryKey = `memory_${userId}`;

// lấy memory cũ
const memory = store[memoryKey] || [];

return [
  {
    json: {
      ...input,
      user_id: userId,
      history: memory.join("\n")
    }
  }
];

