const input = $input.first().json;

const userId = input.source_user || input.user_id || input.user || "anonymous";

// ✅ FIX: lấy reply cho chắc chắn
const reply = $node["Parse LLM JSON Safe"].json.reply || "";

const store = $getWorkflowStaticData("global");

const memoryKey = `memory_${userId}`;

let memory = store[memoryKey] || [];

// Lưu lượt hiện tại
memory.push("User: " + (input.comment || ""));
memory.push("Bot: " + reply);

// Giữ 5 lượt gần nhất = 10 dòng User/Bot
memory = memory.slice(-10);

// Save lại memory
store[memoryKey] = memory;

return [
  {
    json: {
      ...input,
      reply: reply,
      memory_saved: true,
      memory_turns: memory.length
    }
  }
];

const rows = $input.all().map(i => i.json);
const base = $node["Normalize + Basic Filter"].json;

// =====================
// NORMALIZE
// =====================
function removeVietnameseTones(str) {
  return (str || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d").replace(/Đ/g, "D");
}

function normalize(str) {
  return removeVietnameseTones(str)
    .toLowerCase()
    .trim();
}

const comment = normalize(base.comment || "");

// =====================
// ✅ PURCHASE INTENT
// =====================
const purchaseKeywords = [
  "da mua",
  "da chot",
  "chot don",
  "chot nhe",
  "ok chot",
  "mua roi",
  "dat hang roi",
  "toi lay",
  "lay 1",
  "lay 2",
  "chot 1",
  "chot 2"
];

function detectPurchaseIntent(comment) {
  for (const k of purchaseKeywords) {
    if (comment.includes(normalize(k))) {
      return true;
    }
  }
  return false;
}

const isPurchaseConfirmed = detectPurchaseIntent(comment);

// =====================
// ✅ CATEGORY
// =====================
const categoryKeywords = {
  "lau san": ["lau san", "lau nha", "floor"],
  "bep": ["bep", "dau mo"],
  "toilet": ["toilet", "wc", "nha ve sinh", "nha tam"],
  "khu mui": ["mui hoi", "khu mui"]
};

function detectCategory(comment) {
  for (const [key, keywords] of Object.entries(categoryKeywords)) {
    for (const k of keywords) {
      if (comment.includes(normalize(k))) {
        return key;
      }
    }
  }
  return null;
}

const detectedCategory = detectCategory(comment);

// =====================
// ✅ EXTRACT QUANTITY
// =====================
const quantityMatch = comment.match(/\b(\d+)\b/);
const quantity = quantityMatch ? parseInt(quantityMatch[1]) : null;

// =====================
// ✅ SCORING
// =====================
function scoreProduct(name, comment, category) {
  let score = 0;
  if (!name) return 0;

  const n = normalize(name);

  // ✅ match category
  if (category && n.includes(category)) {
    score += 5;
  }

  // ✅ exact name match
  if (comment.includes(n)) {
    score += 3;
  }

  // ✅ partial match
  const words = n.split(" ");
  for (const w of words) {
    if (w.length > 2 && comment.includes(w)) {
      score += 1;
    }
  }

  return score;
}

// =====================
// ✅ MATCH PRODUCT (skip nếu đã chốt)
// =====================
let productVerified = null;
let bestScore = 0;

if (!isPurchaseConfirmed) {

  let bestMatch = null;

  for (const r of rows) {
    const score = scoreProduct(r.Name, comment, detectedCategory);

    if (score > bestScore) {
      bestScore = score;
      bestMatch = r;
    }
  }

  if (bestMatch && bestScore > 0) {
    productVerified = {
      name: bestMatch.Name,
      price: bestMatch.Price,
      desc: (bestMatch.Description || "").slice(0, 120)
    };
  }
}

// =====================
// ✅ OUTPUT
// =====================
return [{
  json: {
    ...base,
    product: productVerified,
    detected_category: detectedCategory,
    match_score: bestScore,
    is_purchase_intent: isPurchaseConfirmed,
    quantity: quantity
  }
}];

